        return ""
    res = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            res.append(f"{prev}{count}")
            prev = c
            count = 1
    res.append(f"{prev}{count}")
    return "".join(res)
