def merge_intervals(xs: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not xs:
        return []
    xs = sorted(xs)
    merged = [xs[0]]
    for s, e in xs[1:]:
        ls, le = merged[-1]
        if s <= le:
            merged[-1] = (ls, le if le > e else e)
        else:
            merged.append((s, e))
    return merged
